cat > bot.mjs <<'EOF'
import fs from "node:fs";

const QUIET_START = "22:00"; // quiet hours for push: 22:00 to before 07:00 recipient-local
const QUIET_END = "07:00";
const MAX_WAIT_MS = 2000;

function stateDir() {
  const dir = process.env.STATE_DIR;
  if (!dir) throw new Error("STATE_DIR is not set");
  fs.mkdirSync(dir, { recursive: true });
  return dir;
}

function toMs(now) {
  const ms = now instanceof Date ? now.getTime() : typeof now === "number" ? now : Date.parse(now);
  if (!Number.isFinite(ms)) throw new Error("now is not a valid time");
  return ms;
}

const iso = (ms) => new Date(ms).toISOString();
const keyPart = (s) => encodeURIComponent(String(s));

async function waitForRecord(dir, key) {
  const end = Date.now() + MAX_WAIT_MS;
  for (;;) {
    const rec = gkRead(dir, key);
    if (rec || Date.now() >= end) return rec;
    await new Promise((r) => setTimeout(r, 25));
  }
}

export async function deliver({ user, candidate, now, transport, consentStore }) {
  const dir = stateDir();
  const nowMs = toMs(now);
  const none = (reason, resumeAt = null) => ({ push: false, inApp: false, reason, resumeAt });
  const type = candidate.type;

  // User's own choice per kind of notification: false = off. Missing = never asked (unknown, not "no").
  if (user.categories && user.categories[type] === false) {
    return none(`You switched off ${type} notifications in notification settings.`);
  }

  // Consent: false or absent means off; a failing store means unknown, so hold.
  let consents;
  try {
    consents = await consentStore.get(user.id);
  } catch {
    return none("Consent could not be checked right now, so nothing was sent.");
  }
  if (!consents || consents[type] !== true) {
    return none(`There is no consent on record for ${type} notifications.`);
  }

  // Push-only holds (the silent in-app item is still produced).
  let pushReason = null;
  let resumeAt = null;
  let pushOk = true;
  const zone = user.timezone;
  if (user.notificationsPermitted === false) {
    pushOk = false;
    pushReason = "Notifications are turned off for this app in the phone's settings, so only the in-app item was added.";
  } else if (user.snoozedUntil && Date.parse(user.snoozedUntil) > nowMs) {
    pushOk = false;
    const until = Date.parse(user.snoozedUntil);
    resumeAt = iso(until);
    pushReason = Number.isFinite(until) && typeof zone === "string" && gkZoneOk(zone)
      ? `Snoozed until ${gkFmt(until, zone)}, so only the in-app item was added.`
      : "Snoozed by the user, so only the in-app item was added.";
  } else if (typeof zone !== "string" || !gkZoneOk(zone)) {
    pushOk = false;
    pushReason = "The time zone is unknown, so quiet hours cannot be checked and the push was held; only the in-app item was added.";
  } else if (!gkInWindow(nowMs, zone, QUIET_END, QUIET_START)) {
    pushOk = false;
    const next = gkNextOpen(nowMs, zone, QUIET_END, QUIET_START);
    resumeAt = next == null ? null : iso(next);
    pushReason = `Quiet hours (22:00 to 07:00 local time) are on, so the push was held until ${next == null ? "later" : gkFmt(next, zone)}; only the in-app item was added.`;
  }

  const id = `${keyPart(user.id)}.${keyPart(candidate.id)}`;
  let push = false;
  let reason = pushReason;

  if (pushOk) {
    const pkey = `push.${id}`;
    if (gkClaim(dir, pkey)) {
      let accepted;
      try {
        accepted = await transport.push(user, candidate);
      } catch {
        // Outcome unknown: keep the claim so the push is never sent twice.
        accepted = null;
      }
      if (accepted === true) {
        gkWrite(dir, pkey, { push: true, at: iso(nowMs) });
        push = true;
      } else if (accepted === false) {
        gkUnclaim(dir, pkey); // definitely not sent
        reason = "The phone did not accept the push (for example no device token); only the in-app item was added.";
      } else {
        reason = "The push may or may not have gone out, so it was not retried; only the in-app item was added.";
      }
    } else {
      const rec = await waitForRecord(dir, pkey);
      push = !!(rec && rec.push);
      if (!push) reason = "This briefing is already being sent or was already attempted.";
    }
  }

  // Silent in-app item: once per message id, reported every time.
  const akey = `inapp.${id}`;
  let inApp = false;
  if (gkClaim(dir, akey)) {
    try {
      await transport.inApp(user, candidate);
      gkWrite(dir, akey, { at: iso(nowMs) });
      inApp = true;
    } catch {
      gkUnclaim(dir, akey);
      reason = reason || "The in-app item could not be stored.";
    }
  } else {
    inApp = true;
  }

  return { push, inApp, reason: push ? null : reason, resumeAt: push ? null : resumeAt };
}

export async function recordDismissal(userId, type, now) {
  const dir = stateDir();
  const ms = toMs(now);
  const base = `dismiss.${keyPart(userId)}.${keyPart(type)}`;
  const { n } = gkCount(dir, `${base}.n`, Number.MAX_SAFE_INTEGER);
  gkWrite(dir, `${base}.last`, { at: iso(ms), n });
}
